/**
 * =============================================================================
 * STRATEGY 12.10.1 PARAMETER VALIDATION E2E TESTS
 * =============================================================================
 *
 * Purpose: Validate strategy 12.10.1 parameter handling and trade generation
 * against the bug where URL parameters weren't being applied correctly.
 *
 * Test scenarios:
 * 1. Strategy parameter updates: Verify pt/sl/trg values update when strategy changes
 * 2. Trade interval coverage: Ensure trades appear in both pre-9:35 and post-9:35 intervals
 * 3. Parameter sensitivity: Different pt values should produce different "today's net" results
 *
 * URLs tested:
 * - /backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45
 * - /backtest/2025-11-20?strategy=strategy12.10.1&pt=20&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45
 */

import { expect, Page, test } from "@playwright/test";

test.describe("Strategy 12.10.1 Parameter Validation", () => {
  test.beforeEach(async ({ page }) => {
    // Capture console logs for debugging
    page.on("console", (msg) => {
      console.log(`[browser:${msg.type()}]`, msg.text());
    });
  });

  /**
   * Helper function to wait for backtest page to fully load with trades
   */
  async function waitForBacktestLoaded(page: Page) {
    // Wait for chart container to be visible
    await page.waitForSelector('[data-testid="chart-container"]', { timeout: 10000 });

    // Wait for strategy select to be populated
    await page.waitForFunction(() => {
      const select = document.querySelector('[data-testid="strategy-select"]') as HTMLSelectElement;
      return select && select.options && select.options.length > 0;
    });

    // Wait for trade table to have data (at least loading state cleared)
    await page.waitForSelector('[data-testid="trade-row"]', { timeout: 15000 });

    // Brief pause for any final rendering
    await page.waitForTimeout(500);
  }

  /**
   * Helper function to extract trade data from the trade table
   */
  async function getTradeData(page: Page) {
    const tradeRows = page.locator('[data-testid="trade-row"]');
    return await tradeRows.evaluateAll((rows) =>
      rows.map((row) => {
        const cells = row.querySelectorAll("td");
        return {
          id: cells[0]?.textContent?.trim() || "",
          time: cells[1]?.textContent?.trim() || "",
          type: cells[2]?.textContent?.trim() || "",
          price: cells[3]?.textContent?.trim() || "",
          net: cells[5]?.textContent?.trim() || "",
          note: cells[6]?.textContent?.trim() || "",
        };
      })
    );
  }

  /**
   * Helper function to check if trades exist in both pre-9:35 and post-9:35 intervals
   */
  function validateTradeIntervals(tradeData: Array<{ time: string; type: string }>) {
    const pre935Trades = tradeData.filter((trade) => {
      const timeMatch = trade.time.match(/(\d{2}:\d{2}:\d{2})/);
      if (!timeMatch) return false;
      const timeStr = timeMatch[1];
      return timeStr < "09:35:00" && trade.type.includes("Open");
    });

    const post935Trades = tradeData.filter((trade) => {
      const timeMatch = trade.time.match(/(\d{2}:\d{2}:\d{2})/);
      if (!timeMatch) return false;
      const timeStr = timeMatch[1];
      return timeStr >= "09:35:00" && trade.type.includes("Open");
    });

    return {
      pre935Count: pre935Trades.length,
      post935Count: post935Trades.length,
      hasBothIntervals: pre935Trades.length > 0 && post935Trades.length > 0,
    };
  }

  test("strategy parameter updates reflect URL values correctly", {
    annotation: {
      type: "description",
      description: "Verifies that URL parameters (pt, sl, trg) are correctly applied when loading strategy 12.10.1. This tests the fix for the bug where URL parameters weren't being properly hydrated into the UI controls."
    }
  }, async ({ page }) => {
    // Navigate to the specific URL with pt=44
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    // Verify strategy is correctly selected
    const strategySelect = page.getByTestId("strategy-select");
    await expect(strategySelect).toHaveValue("strategy12.10.1");

    // Verify parameter values match URL
    const ptSelect = page.getByTestId("pt-select");
    const slSelect = page.getByTestId("sl-select");
    const trgSelect = page.getByTestId("trg-select");

    await expect(ptSelect).toHaveValue("44");
    await expect(slSelect).toHaveValue("10");
    await expect(trgSelect).toHaveValue("8");
  });

  test("strategy changes update parameter controls dynamically", {
    annotation: {
      type: "description",
      description: "Tests that changing the strategy selection dynamically updates the parameter controls (pt, sl, trg) to reflect the new strategy's values, ensuring proper parameter synchronization."
    }
  }, async ({ page }) => {
    // Start with strategy12.10.1
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    // Verify initial parameters
    await expect(page.getByTestId("pt-select")).toHaveValue("44");
    await expect(page.getByTestId("sl-select")).toHaveValue("10");
    await expect(page.getByTestId("trg-select")).toHaveValue("8");

    // Change to a different strategy
    const strategySelect = page.getByTestId("strategy-select");
    await strategySelect.selectOption("935startchange");

    // Wait for parameter updates
    await page.waitForTimeout(1000);

    // Parameters should update to different values (935startchange has different defaults)
    const newPtValue = await page.getByTestId("pt-select").inputValue();
    const newSlValue = await page.getByTestId("sl-select").inputValue();
    const newTrgValue = await page.getByTestId("trg-select").inputValue();

    // At least one parameter should be different from the original values
    const paramsChanged = newPtValue !== "44" || newSlValue !== "10" || newTrgValue !== "8";
    expect(paramsChanged, `Parameters should update when strategy changes. Original: pt=44,sl=10,trg=8; New: pt=${newPtValue},sl=${newSlValue},trg=${newTrgValue}`).toBeTruthy();
  });

  test("trades appear in both pre-9:35 and post-9:35 intervals for strategy 12.10.1", {
    annotation: {
      type: "description",
      description: "Validates that strategy 12.10.1 generates trades in both the morning session (pre-9:35 ET) and the reset session (post-9:35 ET), ensuring the 9:35 session reset logic works correctly."
    }
  }, async ({ page }) => {
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    // Get trade data
    const tradeData = await getTradeData(page);
    expect(tradeData.length, "Should have at least some trades").toBeGreaterThan(0);

    // Validate trade intervals
    const intervalValidation = validateTradeIntervals(tradeData);

    console.log(`Trade intervals: Pre-9:35=${intervalValidation.pre935Count}, Post-9:35=${intervalValidation.post935Count}`);

    expect(intervalValidation.hasBothIntervals,
      `Should have trades in both intervals. Pre-9:35: ${intervalValidation.pre935Count}, Post-9:35: ${intervalValidation.post935Count}`
    ).toBeTruthy();
  });

  test("different pt values produce different today's net results", {
    annotation: {
      type: "description",
      description: "Tests that changing the profit target (pt) parameter from 44 to 20 produces measurably different 'today's net' results, validating that parameter changes actually affect trade outcomes."
    }
  }, async ({ page }) => {
    // Test with pt=44 first
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    const todaysNet44 = await page.getByTestId("todays-net").textContent();
    const netValue44 = parseFloat(todaysNet44?.replace(/[$,]/g, "") || "0");

    // Navigate to pt=20 version
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=20&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    const todaysNet20 = await page.getByTestId("todays-net").textContent();
    const netValue20 = parseFloat(todaysNet20?.replace(/[$,]/g, "") || "0");

    console.log(`Today's Net - pt=44: ${netValue44}, pt=20: ${netValue20}`);

    // The net values should be different (pt=44 should generally produce higher net than pt=20 for profitable trades)
    expect(netValue44, `pt=44 net (${netValue44}) should be different from pt=20 net (${netValue20})`).not.toBe(netValue20);

    // For strategy 12.10.1, higher pt values typically produce higher net returns
    // (though this could vary based on specific market conditions)
    expect(Math.abs(netValue44 - netValue20), `Net difference should be meaningful. pt=44: ${netValue44}, pt=20: ${netValue20}`).toBeGreaterThan(0);
  });

  test("pt parameter changes update trade table and summary stats", {
    annotation: {
      type: "description",
      description: "Verifies that changing the pt parameter dynamically (via dropdown) immediately updates both the trade table and summary statistics, ensuring real-time parameter sensitivity."
    }
  }, async ({ page }) => {
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=44&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    // Get initial state
    const initialNet = await page.getByTestId("todays-net").textContent();
    const initialTradeCount = await page.getByTestId("num-trades").textContent();

    // Change pt parameter
    const ptSelect = page.getByTestId("pt-select");
    await ptSelect.selectOption("20");

    // Wait for updates
    await page.waitForTimeout(1000);

    // Verify changes occurred
    const updatedNet = await page.getByTestId("todays-net").textContent();
    const updatedTradeCount = await page.getByTestId("num-trades").textContent();

    const netChanged = initialNet !== updatedNet;
    const tradeCountChanged = initialTradeCount !== updatedTradeCount;

    expect(netChanged || tradeCountChanged,
      `At least one metric should change when pt parameter changes. Initial: net=${initialNet}, trades=${initialTradeCount}; Updated: net=${updatedNet}, trades=${updatedTradeCount}`
    ).toBeTruthy();
  });

  test("strategy 12.10.1 generates valid trade entries after 9:35 reset", {
    annotation: {
      type: "description",
      description: "Specifically tests that strategy 12.10.1 generates valid trade entries after the 9:35 ET session reset, which is a key differentiator from other strategies like 935startchange."
    }
  }, async ({ page }) => {
    await page.goto("/backtest/2025-11-20?strategy=strategy12.10.1&pt=20&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45");
    await waitForBacktestLoaded(page);

    const tradeData = await getTradeData(page);

    // Find trades after 9:35 ET
    const post935Entries = tradeData.filter((trade) => {
      const timeMatch = trade.time.match(/(\d{2}:\d{2}:\d{2})/);
      if (!timeMatch) return false;
      const timeStr = timeMatch[1];
      return timeStr >= "09:35:00" && trade.type.includes("Open");
    });

    expect(post935Entries.length,
      `Should have at least one trade entry after 9:35 ET reset. Found ${post935Entries.length} post-9:35 entries`
    ).toBeGreaterThan(0);

    // Log the post-9:35 entries for verification
    console.log("Post-9:35 trade entries:");
    post935Entries.forEach((trade, idx) => {
      console.log(`${idx + 1}. ${trade.time} - ${trade.type} @ ${trade.price}`);
    });
  });
});

