/**
 * Helper function to extract trade data from the trade table
 */
async function getTradeData(page: Page) {
  const tradeRows = page.locator('[data-testid="trade-row"]');
  return await tradeRows.evaluateAll((rows) =>
    rows.map((row) => {
      const cells = row.querySelectorAll("td");
      return {
        id: cells[0]?.textContent?.trim() || "",
        time: cells[1]?.textContent?.trim() || "",
        type: cells[2]?.textContent?.trim() || "",
        price: cells[3]?.textContent?.trim() || "",
        net: cells[5]?.textContent?.trim() || "",
        note: cells[6]?.textContent?.trim() || "",
      };
    })
  );
}

/**
 * Helper function to check if trades exist in both pre-9:35 and post-9:35 intervals
 */
function validateTradeIntervals(tradeData: Array<{ time: string; type: string }>) {
  const pre935Trades = tradeData.filter((trade) => {
    const timeMatch = trade.time.match(/(\d{2}:\d{2}:\d{2})/);
    if (!timeMatch) return false;
    const timeStr = timeMatch[1];
    return timeStr < "09:35:00" && trade.type.includes("Open");
  });

  const post935Trades = tradeData.filter((trade) => {
    const timeMatch = trade.time.match(/(\d{2}:\d{2}:\d{2})/);
    if (!timeMatch) return false;
    const timeStr = timeMatch[1];
    return timeStr >= "09:35:00" && trade.type.includes("Open");
  });

  return {
    pre935Count: pre935Trades.length,
    post935Count: post935Trades.length,
    hasBothIntervals: pre935Trades.length > 0 && post935Trades.length > 0,
  };
}

