  // Get trade data
  const tradeData = await getTradeData(page);
  expect(tradeData.length, "Should have at least some trades").toBeGreaterThan(0);

  // Validate trade intervals
  const intervalValidation = validateTradeIntervals(tradeData);

  console.log(`Trade intervals: Pre-9:35=${intervalValidation.pre935Count}, Post-9:35=${intervalValidation.post935Count}`);

  expect(intervalValidation.hasBothIntervals,
    `Should have trades in both intervals. Pre-9:35: ${intervalValidation.pre935Count}, Post-9:35: ${intervalValidation.post935Count}`
  ).toBeTruthy();
});

