/**
 * =============================================================================
 * UNIT TESTS: Strategy 12.10.1 Parameter Validation
 * =============================================================================
 *
 * Purpose: Validate strategy 12.10.1 parameter handling and trade generation
 * against the bug where URL parameters weren't being applied correctly.
 *
 * Test scenarios:
 * 1. Parameter parsing: Verify pt/sl/trg parameters are correctly extracted from URLs
 * 2. Trade generation: Ensure different pt values produce different trade results
 * 3. Strategy behavior: Validate 9:35 reset logic works correctly
 */

import { describe, it, expect } from "vitest";
import { generateAlgoTrades, buildBacktestParams } from "../../src/lib/backtest";
import { readFileSync } from "node:fs";
import { join } from "node:path";

describe("Strategy 12.10.1 Parameter Validation", () => {
  const testDate = "2025-11-20";
  const candlesPath = join(process.cwd(), "src", "public", "data", "backtest", "candles", `${testDate}.json`);

  // Load test candle data
  let candleData: any[];
  try {
    candleData = JSON.parse(readFileSync(candlesPath, "utf-8"));
  } catch (error) {
    console.warn(`Could not load candle data for ${testDate}, some tests may be skipped`);
    candleData = [];
  }

  describe("Parameter handling validation", () => {
    it("should generate different results for pt=44 vs pt=20", async () => {
      if (candleData.length === 0) {
        console.warn("Skipping test: no candle data available");
        return;
      }

      // Test with pt=44
      const params44 = buildBacktestParams({
        strategy: "strategy12.10.1",
        pt: 44,
        sl: 10,
        trg: 8,
        cutoffTime: "09:45",
        candleType: "1s"
      });

      const trades44 = await generateAlgoTrades({
        ...params44,
        candles: candleData,
        date: testDate
      });

      // Test with pt=20
      const params20 = buildBacktestParams({
        strategy: "strategy12.10.1",
        pt: 20,
        sl: 10,
        trg: 8,
        cutoffTime: "09:45",
        candleType: "1s"
      });

      const trades20 = await generateAlgoTrades({
        ...params20,
        candles: candleData,
        date: testDate
      });

      // Calculate net results
      const net44 = trades44.reduce((sum, trade) => sum + trade.net, 0);
      const net20 = trades20.reduce((sum, trade) => sum + trade.net, 0);

      console.log(`Strategy 12.10.1 results for ${testDate}:`);
      console.log(`pt=44: ${trades44.length} trades, net = $${net44.toFixed(2)}`);
      console.log(`pt=20: ${trades20.length} trades, net = $${net20.toFixed(2)}`);

      // Results should be different (though which is higher depends on market conditions)
      expect(net44).not.toBe(net20);
    });

    it("should generate trades in both pre-9:35 and post-9:35 intervals", async () => {
      if (candleData.length === 0) {
        console.warn("Skipping test: no candle data available");
        return;
      }

      const params = buildBacktestParams({
        strategy: "strategy12.10.1",
        pt: 20,
        sl: 10,
        trg: 8,
        cutoffTime: "09:45",
        candleType: "1s"
      });

      const trades = await generateAlgoTrades({
        ...params,
        candles: candleData,
        date: testDate
      });

      // Find trades in different time intervals
      const pre935Trades = trades.filter(trade => {
        const tradeTime = new Date(trade.time);
        const hour = tradeTime.getHours();
        const minute = tradeTime.getMinutes();
        return hour < 9 || (hour === 9 && minute < 35);
      });

      const post935Trades = trades.filter(trade => {
        const tradeTime = new Date(trade.time);
        const hour = tradeTime.getHours();
        const minute = tradeTime.getMinutes();
        return hour > 9 || (hour === 9 && minute >= 35);
      });

      console.log(`Trade distribution for ${testDate}:`);
      console.log(`Pre-9:35 trades: ${pre935Trades.length}`);
      console.log(`Post-9:35 trades: ${post935Trades.length}`);

      // Strategy 12.10.1 should generate trades in both intervals
      expect(pre935Trades.length + post935Trades.length).toBe(trades.length);
      expect(trades.length).toBeGreaterThan(0);
    });

    it("should handle parameter edge cases correctly", async () => {
      if (candleData.length === 0) {
        console.warn("Skipping test: no candle data available");
        return;
      }

      // Test various parameter combinations
      const testCases = [
        { pt: 10, sl: 5, trg: 4 },
        { pt: 50, sl: 15, trg: 12 },
        { pt: 25, sl: 8, trg: 6 }
      ];

      for (const testParams of testCases) {
        const params = buildBacktestParams({
          strategy: "strategy12.10.1",
          ...testParams,
          cutoffTime: "09:45",
          candleType: "1s"
        });

        const trades = await generateAlgoTrades({
          ...params,
          candles: candleData,
          date: testDate
        });

        // Should generate some trades for valid parameters
        expect(trades.length).toBeGreaterThanOrEqual(0);

        console.log(`Parameters ${JSON.stringify(testParams)}: ${trades.length} trades`);
      }
    });
  });
});

